import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = readInt(in);
        StringBuilder sb = new StringBuilder();
        if (n <= 0) {
            System.out.print("\n");
            return;
        }
        boolean[] seen = new boolean[n + 1];
        int last = n; // rightmost position that is still 0
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out), 1 << 16));
        for (int k = 1; k <= n; k++) {
            int p = readInt(in);
            seen[p] = true;
            while (last > 0 && seen[last]) last--;
            sb.append(k - (n - last) + 1).append(k == n ? '\n' : ' ');
            if (sb.length() > 1 << 16) {
                out.write(sb.toString());
                sb.setLength(0);
            }
        }
        out.write(sb.toString());
        out.flush();
    }

    private static int readInt(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != -1 && c <= ' ') c = in.read();
        if (c == -1) return 0;
        int x = 0;
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = in.read();
        }
        return x;
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	writer := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer writer.Flush()
	readInt := func() int {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		x := 0
		for err == nil && c > ' ' {
			x = x*10 + int(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	n := readInt()
	if n == 0 {
		writer.WriteByte('\n')
		return
	}
	seen := make([]bool, n+1)
	last := n // rightmost position that is still 0
	buf := make([]byte, 0, 16)
	for k := 1; k <= n; k++ {
		p := readInt()
		seen[p] = true
		for last > 0 && seen[last] {
			last--
		}
		buf = strconv.AppendInt(buf[:0], int64(k-(n-last)+1), 10)
		if k == n {
			buf = append(buf, '\n')
		} else {
			buf = append(buf, ' ')
		}
		writer.Write(buf)
	}
}
